"""Generate documentation counts and model results from the database."""
import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(root / "src"))
from kkr_scout.database import get_engine
from kkr_scout.service import read_meta, rows

with get_engine(root).connect() as conn:
    inventory = read_meta(conn, "inventory")
    quality = read_meta(conn, "data_quality")
    model = read_meta(conn, "model_summary")
    methodology = read_meta(conn, "methodology")
    design = read_meta(conn, "design", {})
    eda = read_meta(conn, "eda", {})
    teams = rows(conn, "SELECT team,COUNT(*) AS matches FROM (SELECT match_id,team1 AS team FROM matches WHERE competition='Indian Premier League' UNION SELECT match_id,team2 AS team FROM matches WHERE competition='Indian Premier League') q GROUP BY team ORDER BY matches DESC")

lines = ["# KKR Auction Scout", "", "A local scouting website built from the uploaded Cricsheet match files. It serves a React build from FastAPI and stores source data and batch scores in SQLite. DATABASE_URL selects PostgreSQL.", "", "## Run", "", "Python 3.11 or newer is required. The Git checkout includes source code and the original match JSON files under data/raw/cricsheet. Build the frontend before starting the server.", "", "```powershell", "python -m venv .venv", ".\\.venv\\Scripts\\python.exe -m pip install '.[test]'", ".\\.venv\\Scripts\\python.exe run.py", "```", "", "The last command inventories, ingests, scores and serves. Open http://127.0.0.1:8000. On Linux or macOS use `.venv/bin/python`. Ingestion skips unchanged files by hash. A changed manual override file triggers identity resolution again. Raw files are never edited.", "", "For a source frontend build: `cd frontend`, `npm ci`, `npm run build`. Node 22 is used by Docker and CI. For pipeline-only work use `python run.py prepare`; to serve an already prepared database use `python run.py serve`.", "", "## Uploaded data", "", "Counts below are read from the database inventory. Delivery rows include wides, no-balls, super overs and interrupted innings.", "", "| Competition | Matches | Innings | Delivery rows | Legal balls | Dates |", "|---|---:|---:|---:|---:|---|"]
for r in inventory["competitions"]:
    lines.append(f"| {r['competition']} | {r['matches']:,} | {r['innings']:,} | {r['deliveries']:,} | {r['legal_balls']:,} | {r['min_date']} to {r['max_date']} |")
lines += ["", "All supplied sporting files are Tier A ball-by-ball. Tier B scorecard tables exist but remain empty because no such source was uploaded. No parser is fabricated for an unknown scorecard format. See [inventory](data/inventory.md) and [per-file hashes](data/upload_manifest.csv).", "", "This is a selected match archive. The supplied README.txt describes a KKR archive, while the merged uploaded folder contains more IPL files. Actual IPL team occurrences from SQL:", "", "| Source team spelling | Matches |", "|---|---:|"]
for r in teams:
    lines.append(f"| {r['team']} | {r['matches']} |")
lines += ["", "Source team spellings remain intact. Historical match rosters are participants, not a current squad or an auction pool.", "", "## Counting and scoring", ""]
for section in methodology["sections"]:
    lines += [f"**{section['title']}.** {section['text']}", ""]
lines += ["Minimum samples are policy settings stored with the batch model:", "", "| Setting | Minimum |", "|---|---:|"]
for key,value in methodology["thresholds"].items():
    lines.append(f"| {key} | {value} |")
lines += ["", "Ranks and displayed score intervals are persisted in player_scores. Below the discipline minimum, scores and ranks are absent and insights say `Insufficient data`. The reported intervals are model intervals with the assumptions stated above. They do not establish predictive accuracy.", "", f"**Measured model summary.** {model['ranked_players']} players meet an overall sample threshold. {model['archetypes']} usage archetypes were fitted. Adjustment label: {model['adjustment_label']}.", "", "**League adjustment, exactly as computed:**", "", "```json", json.dumps(model["league_adjustment"], indent=2), "```", "", "**Back-test, exactly as computed:**", "", "```json", json.dumps(model["backtest"], indent=2), "```", "", "The requested past-auction uncapped-player test is unavailable for the reason given in this result. The separate holdout is a descriptive check. Training uses earlier records and test samples use the final uploaded calendar year; the Methodology page reports its sample and uncertainty.", "", "Six phase findings with sample sizes and confidence intervals are generated in [EDA](reports/eda.md). The [notebook](notebooks/uploaded_sample_eda/uploaded_sample_eda.ipynb) reads them through SQL. " + eda.get("method", ""), "", "## Data quality", "", "| Check | Status | Failures | Detail |", "|---|---|---:|---|"]
for r in quality:
    lines.append(f"| {r['check']} | {r['status']} | {r['failures'] if r['failures'] is not None else 'Unavailable'} | {r.get('detail','')} |")
lines += ["", "The raw files contain annotated umpire miscounts. These are preserved and tested against the source annotations. Summing deliveries verifies internal consistency; it does not replace independent scorecard reconciliation.", "", "## Squad and planner", "", "Squad file not loaded. The Squad Gaps page links to a working blank squad template. Supply `data/squad.csv` with database player_id values from `/players`, and optionally `data/constraints.csv` and `data/prices.csv`, then rerun the pipeline. Templates contain headers only. No retained player, purse or price was inferred or fetched from the web.", "", "Price data not provided. The current planner maximizes the sum of precomputed scores with an analyst-entered slot count and minimum batting/bowling coverage. These are scenario settings, not an asserted team purse or slot limit. It excludes explicitly removed players and uploaded squad members. PuLP is not needed; SciPy MILP performs integer selection. Results include the next highest unselected values, which are not separate optimized squads.", "", "When uploaded prices and a purse are available, only priced candidates enter a purse-constrained run. Candidate overseas eligibility is absent, so overseas constraints return a specific validation error. Uploaded squad role, hand and bowling type fields support coverage; absent fields remain unknown. Budget sensitivity, current retained coverage, overseas balance, age filters, spin/pace splits and auction availability are unavailable with these uploads. The site omits unsupported input controls.", "", "## API and traceability", "", "FastAPI documents the working endpoints at `/docs`. Core endpoints exist at `/players`, `/players/{id}`, `/squad/gaps`, `/optimize` and `/compare`, with `/api` aliases for the frontend. `/api/dashboard`, `/api/methodology`, `/health` and template downloads also work. Inputs are validated with Pydantic. Scores are read from batch output; requests do not refit the model.", "", "| Screen values | Database origin |", "|---|---|", "| Dashboard counts and chart | matches, innings, deliveries SQL counts by competition/season |", "| Search scores, ranks and intervals | player_scores; participation filters join match_players and matches |", "| Report and compare charts | player_scores.summary_json from regulation deliveries and wickets |", "| Planner total value | sum of selected player_scores.score rows |", "| Methodology samples and results | pipeline_meta inventory, data_quality, methodology, model_summary and eda |", "", "Search filters identify observed participants. Scores retain their scope across all uploaded seasons; filtering a season does not refit scores. API tests compare output values and report chart payloads against SQL. Insights use fixed templates with computed sample sizes and intervals. Source fields absent from the database show `Not in uploaded data`.", "", "```mermaid", "flowchart LR", "  A[Uploaded JSON] --> B[Inventory and hash manifest]", "  B --> C[Idempotent ingestion]", "  C --> D[(SQLite or PostgreSQL)]", "  D --> E[Batch metrics and model]", "  E --> D", "  D --> F[FastAPI and MILP]", "  F --> G[React and Recharts]", "```", "", "## Verification and deployment", "", "Run `pytest -q`. Tests use real uploaded matches, including irregular innings and illegal deliveries. Build the frontend with `npm run build`. Start the server with `python run.py serve`, then run `node scripts/ui-check/ui-check.mjs` from `frontend`. Playwright Chromium must be installed using `npx playwright install chromium` if no existing executable is configured. The browser check visits every page and exercises search, filters, sorting, pagination, report selection, planner constraints, comparisons and downloads.", "", "Docker: `docker compose up --build`. The default stack uses SQLite. For PostgreSQL, set POSTGRES_PASSWORD and a DATABASE_URL that points to the compose postgres service, then run `docker compose -f docker-compose.yml -f compose.postgres.yml up --build`. Credentials belong in environment variables and `.env` is ignored. An initial Alembic migration is supplied: `alembic upgrade head`. The normal first run creates missing tables automatically. Add new migrations for later schema changes.", "", "Docker and a PostgreSQL server are not installed in this workspace. Their runtime paths were not executed here. PostgreSQL SQL/schema portability is checked separately. GitHub Actions runs tests and browser checks for this repository. No public deployment was requested with a destination or credentials.", "", "## Design and source attribution", "", "Design provenance and extracted values are stored in [tokens](design/tokens.json). The site uses a text wordmark and no copied logo or player photos. Colors, typography and spacing are defined as CSS variables; dark surfaces and text pairs are checked for WCAG AA contrast. See the design provenance result in the Methodology page.", "", "Cricsheet match data is supplied under the Open Data Commons Attribution License. Preserve README.txt, LICENSE.txt and source attribution when redistributing the data. The archive provenance is in the supplied README.txt.", "", "Independent project. Not affiliated with or endorsed by KKR or the IPL.", ""]
lines.extend(["Design provenance: " + design.get("provenance", "Not in uploaded data"), "", "![Dashboard](reports/dashboard-desktop.png)", ""])
run_line = next(i for i,line in enumerate(lines) if line == r".\.venv\Scripts\python.exe run.py")
lines[run_line:run_line] = ["npm --prefix frontend ci", "npm --prefix frontend run build"]
layout = root / "docs/repository_layout.md"
if layout.exists():
    lines.extend(layout.read_text(encoding="utf-8").splitlines())
(root / "README.md").write_text("\n".join(lines), encoding="utf-8")
(root / "reports/database_snapshot.json").write_text(json.dumps({"inventory":inventory,"quality":quality,"model":model,"eda":eda,"design":design}, indent=2), encoding="utf-8")
print("Wrote README.md and reports/database_snapshot.json from SQL")
